{"actions":[{"action":"success_contract","content":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1 6665 connects to the VM and shows a login prompt, then leave it running and block until it is ready.","required_artifacts":["A running QEMU process booting /app/alpine.iso","A listening TCP service on 127.0.0.1:6665 forwarded to the VM console/login service"],"required_behaviors":["QEMU must be started in the background","Port 6665 on localhost must accept telnet connections","Connecting with telnet 127.0.0.1 6665 must present a login prompt","The VM must remain running after readiness is reached"],"known_invalid_patterns":["Merely locating the ISO file","Starting QEMU without port forwarding to 6665","Returning before the telnet login prompt is reachable","Smoke checks that do not verify telnet login prompt behavior"],"verification_plan":["Inspect available tools and filesystem for the ISO and QEMU availability","Start QEMU with appropriate serial/monitor forwarding to localhost:6665 in the background","Measure readiness by connecting to 127.0.0.1:6665 and confirming the login prompt appears","Keep the VM process running after readiness is confirmed"],"finalization_evidence_required":["Receipt-backed evidence that QEMU was launched with /app/alpine.iso","Receipt-backed evidence that 127.0.0.1:6665 became reachable","Receipt-backed evidence that telnet to 127.0.0.1:6665 showed a login prompt"],"notes":["Prerequisites like tool availability are not success by themselves; the functional telnet/login behavior is the target."]}},{"action":"plan_update","content":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1 6665 connects to the VM and shows a login prompt, then leave it running and block until it is ready.","current_focus":"Discover available tools and launch QEMU with localhost port 6665 forwarding.","implementation_approach":["Inspect filesystem and tool availability","Determine the correct QEMU invocation for Alpine ISO boot with serial console exposed on tcp:127.0.0.1:6665","Run QEMU in the background","Probe readiness by connecting to the telnet port and checking for the login prompt"],"validation_strategy":["Use measured evidence from process launch and port readiness","Confirm telnet connection reaches a login prompt, not just an open port"],"verification_test_strategy":["If needed, use raw_bash to inspect /app and qemu binaries","Use probe_service or a direct telnet-style connection to verify readiness"],"known_bad_behavior":["Treating file existence or process start as sufficient","Stopping after port open without login prompt","Launching QEMU without leaving it running"],"evidence_gaps":["Need confirmation of QEMU binary and exact console forwarding syntax","Need receipt-backed proof of login prompt on 127.0.0.1:6665"],"risks":["QEMU may not be installed","The ISO may require specific boot parameters or console settings"],"next_steps":["Inspect environment for qemu and the ISO","Launch VM with serial console forwarding","Verify telnet login prompt"],"finalization_evidence_required":["Receipt-backed launch evidence","Receipt-backed telnet readiness evidence","Receipt-backed login prompt evidence"]}}]}
